def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    # Each 5 is a ray origin; trace upward, carrying the last encountered color.
    for c in range(w):
        seeds = [r for r in range(h) if out[r][c] == 5]
        for seed in seeds:
            color = 5
            for r in range(seed - 1, -1, -1):
                if out[r][c] == 0:
                    out[r][c] = color
                else:
                    color = out[r][c]
    return out
